#!/usr/bin/env python3
"""Verify every docs.openaev.io link in the application code against the built docs site.

Each https://docs.openaev.io/latest/<path>[#anchor] link found in the API, model and
front sources must match a page of the MkDocs build output (<site>/<path>/index.html),
and its anchor must be an id on that page. Redirect pages generated by mkdocs-redirects
are followed to their target. Build the site first: `mkdocs build` in docs/.

Usage: check-docs-links.py [site-dir]   (default: docs/site)
"""

import re
import subprocess
import sys
from functools import cache
from pathlib import Path
from urllib.parse import unquote, urljoin, urlsplit

REPO = Path(__file__).resolve().parents[2]
SOURCE_DIRS = ["openaev-api/src", "openaev-model/src", "openaev-front/src"]
SOURCE_SUFFIXES = {".properties", ".java", ".ts", ".tsx", ".js", ".jsx"}
MAX_REDIRECTS = 5

URL_RE = re.compile(r"https://docs\.openaev\.io[^\s\"'`<>)\\]*")
REFRESH_RE = re.compile(r"""http-equiv=["']refresh["'][^>]*content=["']\d+;\s*url=([^"']+)["']""", re.I)
ID_RE = re.compile(r"""\b(?:id|name)=["']([^"']+)["']""")


def page_file(site: Path, url_path: str) -> Path | None:
    for candidate in (site / url_path / "index.html", site / url_path):
        if candidate.is_file():
            return candidate
    return None


@cache
def read_page(page: Path) -> str:
    return page.read_text(encoding="utf-8")


def follow_redirects(site: Path, url_path: str) -> tuple[str, Path | None]:
    """Return the final URL path and its page, following meta-refresh redirect pages."""
    for _ in range(MAX_REDIRECTS):
        page = page_file(site, url_path)
        if page is None:
            return url_path, None
        refresh = REFRESH_RE.search(read_page(page))
        if not refresh:
            return url_path, page
        target = urlsplit(urljoin(f"/{url_path}/", refresh.group(1))).path
        url_path = unquote(target).strip("/")
    return url_path, None


def check_url(site: Path, url: str) -> str | None:
    parts = urlsplit(url)
    segments = [s for s in parts.path.split("/") if s]
    if not segments:
        return None
    if segments[0] != "latest":
        return "link must start with /latest/"
    url_path, page = follow_redirects(site, "/".join(segments[1:]))
    if page is None:
        return f"no page {url_path or 'index'} in the built docs site"
    if parts.fragment and parts.fragment not in ID_RE.findall(read_page(page)):
        return f"no anchor #{parts.fragment} on {page.relative_to(site).as_posix()}"
    return None


def source_files() -> list[Path]:
    listed = subprocess.run(
        ["git", "ls-files", "--", *SOURCE_DIRS],
        cwd=REPO, check=True, capture_output=True, text=True,
    ).stdout.splitlines()
    return [REPO / f for f in listed if Path(f).suffix in SOURCE_SUFFIXES]


def main() -> int:
    site = Path(sys.argv[1]) if len(sys.argv) > 1 else REPO / "docs" / "site"
    if not (site / "index.html").is_file():
        print(f"::error::{site} is not a built MkDocs site: run `mkdocs build` in docs/ first.")
        return 2

    checked, errors = 0, []
    for file in source_files():
        rel = file.relative_to(REPO).as_posix()
        for line_no, line in enumerate(file.read_text(encoding="utf-8").splitlines(), 1):
            for url in URL_RE.findall(line):
                checked += 1
                error = check_url(site, url)
                if error:
                    errors.append((rel, line_no, url, error))

    for rel, line_no, url, error in errors:
        print(f"::error file={rel},line={line_no}::{url}: {error}")
    print(f"Checked {checked} docs link(s), {len(errors)} broken.")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
